  'hrSpace.coreModulesDesc': { en: 'Qualifications, goals, dialogue, documents, training, workforce, onboarding, attendance', zh: '资质、目标、对话、文档、培训、人力、入职与考勤', es: 'Cualificaciones, objetivos, diálogo, documentos, formación, plantilla, incorporación, asistencia', fr: 'Qualifications, objectifs, dialogue, documents, formation, effectifs, onboarding, présences', de: 'Qualifikationen, Ziele, Dialoge, Dokumente, Schulungen, Personalplanung, Onboarding, Anwesenheit', ru: 'Квалификации, цели, диалоги, документы, обучение, планирование персонала, онбординг, учёт времени', pt: 'Qualificações, objetivos, diálogo, documentos, formação, quadros, integração, assiduidade' },
