  'hrSpace.talentSourcingDesc': { en: 'Roadmap: optional integrations with professional networks and job platforms (OAuth, APIs, and partner agreements required).', zh: '路线图：可选对接职业社交网络与招聘平台（需 OAuth、API 与合作伙伴协议）。', es: 'Hoja de ruta: integraciones opcionales con redes profesionales y portales (OAuth, APIs y acuerdos de partners).', fr: 'Feuille de route : intégrations optionnelles avec réseaux pros et job boards (OAuth, API, accords partenaires).', de: 'Roadmap: optionale Anbindung an berufliche Netzwerke und Jobplattformen (OAuth, APIs, Partnerverträge erforderlich).', ru: 'Дорожная карта: опциональные интеграции с профсетями и job-площадками (OAuth, API, партнёрские соглашения).', pt: 'Roteiro: integrações opcionais com redes profissionais e plataformas de emprego (OAuth, APIs e acordos de parceiros necessários).' },
  'hrSpace.talentBulletLinkedIn': { en: 'Recruiter / Talent Hub–style search and candidate pipeline (official APIs, compliance).', zh: '类 Recruiter / Talent Hub 的搜索与候选人管道（官方 API、合规）。', es: 'Búsqueda estilo Recruiter / Talent Hub y pipeline de candidatos (APIs oficiales, cumplimiento).', fr: 'Recherche type Recruiter / Talent Hub et pipeline candidats (API officielles, conformité).', de: 'Recruiter-/Talent-Hub-Suche und Kandidaten-Pipeline (offizielle APIs, Compliance).', ru: 'Поиск в духе Recruiter / Talent Hub и воронка кандидатов (официальные API, комплаенс).', pt: 'Pesquisa e pipeline de candidatos estilo Recruiter / Talent Hub (APIs oficiais, conformidade).' },
